QUESTIONS.push(

  // ================= Mission Mode Projects & Digital Platforms (50) =================
  { id: "mmp-01", topic: "itp-mmp", q: "A Mission Mode Project (MMP) under the National e-Governance Plan is best defined as:", options: ["Any one-off government IT purchase with no defined outcomes", "An individual e-governance project with defined objectives, scope, timelines and measurable service-delivery outcomes, owned by a specific ministry, department or state", "A private company's product launch unrelated to government", "A yearly government IT budget allocation exercise"], answer: 1, exp: "MMP status specifically implies clear milestones, ownership and measurable outcomes, not an unscoped IT purchase or budget line." },
  { id: "mmp-02", topic: "itp-mmp", q: "The National e-Governance Plan (NeGP), under which all MMPs are organized, was approved with the core objective of:", options: ["Restricting e-governance benefits to central government employees only", "Replacing all government departments with private companies", "Making government services accessible to the common man through common service delivery outlets, and ensuring efficiency, transparency and reliability of such services at affordable cost", "Banning the use of paper records in government offices immediately"], answer: 2, exp: "NeGP's stated objective centers on citizen-accessible, efficient, transparent and affordable service delivery through ICT." },
  { id: "mmp-03", topic: "itp-mmp", q: "Mission Mode Projects are classified into how many categories, based on which level of government owns/implements them?", options: ["Three — Central, State, and Integrated", "Two — Central and State only", "Five, with no consistent basis for classification", "MMPs are not classified into any categories"], answer: 0, exp: "MMPs fall into three categories — Central, State and Integrated — based on which level(s) of government own and implement them." },
  { id: "mmp-04", topic: "itp-mmp", q: "Which of the following is a Central Mission Mode Project?", options: ["Land Records", "Employment Exchange", "Common Services Centres (CSC)", "Income Tax (e-filing), administered by a union department"], answer: 3, exp: "Income tax e-filing is administered by the Central Board of Direct Taxes, a union government body, making it a Central MMP." },
  { id: "mmp-05", topic: "itp-mmp", q: "The Passport Seva Project, a Central MMP, is notable for being implemented through:", options: ["A state government initiative with no central involvement", "A public-private partnership model, with a private service provider running Passport Seva Kendras under the Ministry of External Affairs' oversight", "Complete transfer of passport-issuing authority to a private company", "A purely in-house government IT team with no external partner"], answer: 1, exp: "Passport Seva combined private-sector service delivery at Passport Seva Kendras with continued government control over passport issuance authority." },
  { id: "mmp-06", topic: "itp-mmp", q: "MCA21, a Central MMP under the Ministry of Corporate Affairs, primarily enables:", options: ["Physical courtroom case management", "State-level land record digitization", "Municipal property tax collection", "Online company/LLP registration, statutory filing and related corporate compliance services"], answer: 3, exp: "MCA21 digitizes company/LLP registration and statutory compliance filings for the Ministry of Corporate Affairs." },
  { id: "mmp-07", topic: "itp-mmp", q: "Central Excise, one of the original Central Mission Mode Projects, digitized:", options: ["State agricultural subsidies", "Municipal water billing", "Excise duty administration and compliance processes for the union government", "District court case filings"], answer: 2, exp: "Central Excise as an MMP focused on digitizing union government excise duty administration and compliance." },
  { id: "mmp-08", topic: "itp-mmp", q: "Bhoomi, Karnataka's computerized land records system, is a well-known example of which MMP category?", options: ["State MMP, since land records are owned and implemented at the state level", "Central MMP", "Integrated MMP", "Not an MMP at all"], answer: 0, exp: "Land Records is a State MMP, owned and implemented individually by each state government — Bhoomi is Karnataka's implementation." },
  { id: "mmp-09", topic: "itp-mmp", q: "The e-District Mission Mode Project primarily aims to:", options: ["Replace the Passport Seva Project", "Manage only central government pension records", "Provide cloud infrastructure to state governments", "Deliver a range of citizen-centric services (certificates, licenses, grievance redress) electronically at the district administration level"], answer: 3, exp: "e-District is a State MMP delivering routine citizen-facing certificate, licensing and grievance services at the district level." },
  { id: "mmp-10", topic: "itp-mmp", q: "Which MMP category does 'Commercial Taxes' belong to?", options: ["Integrated", "State, since it is owned and administered by individual state governments", "Central", "None of the above"], answer: 1, exp: "Commercial Taxes is a State MMP, administered individually by each state's tax department." },
  { id: "mmp-11", topic: "itp-mmp", q: "Employment Exchange, as a Mission Mode Project, is classified as:", options: ["An Integrated MMP", "A Central MMP", "A State MMP", "A private-sector-only initiative"], answer: 2, exp: "Employment Exchange is implemented and owned by individual state governments, making it a State MMP." },
  { id: "mmp-12", topic: "itp-mmp", q: "e-Courts, a Mission Mode Project computerizing India's judiciary, is classified as:", options: ["A Central MMP only", "A State MMP only", "Not a recognized MMP", "An Integrated MMP, since it spans both central and state judicial administration"], answer: 3, exp: "e-Courts requires coordinated central-state implementation across the judiciary, making it an Integrated MMP." },
  { id: "mmp-13", topic: "itp-mmp", q: "Common Services Centres (CSC), an Integrated MMP, primarily function as:", options: ["Physical access points, often in rural areas, through which citizens can avail multiple government and other digital services", "Data centres exclusively for central ministries", "A private banking network with no government role", "Courtrooms for e-Courts hearings"], answer: 0, exp: "CSCs are last-mile physical access points delivering a bundle of government and other digital services to citizens, especially in rural areas." },
  { id: "mmp-14", topic: "itp-mmp", q: "UID/Aadhaar is categorized as an Integrated MMP primarily because:", options: ["It is used only by a single state government", "Its identity infrastructure is used across both central and state government services, requiring coordinated implementation at both levels", "It has no connection to any MMP category", "It is managed solely by a private company"], answer: 1, exp: "Aadhaar's identity layer underpins services across both central and state governments, which is why it is classified as Integrated." },
  { id: "mmp-15", topic: "itp-mmp", q: "GST, delivered through the GST Network (GSTN), is an Integrated MMP because:", options: ["It is administered entirely by a single state", "It replaced all Mission Mode Projects", "Tax administration under GST spans both central and state tax authorities, requiring integrated implementation", "It has no connection to Mission Mode Projects"], answer: 2, exp: "GST merged central and state indirect taxes into one system, needing coordinated central-state administration through GSTN." },
  { id: "mmp-16", topic: "itp-mmp", q: "The e-Trade Mission Mode Project primarily focuses on:", options: ["Municipal solid waste management", "State employment exchanges", "District court filings", "Facilitating and digitizing documentation/processes involved in international trade, cutting across multiple central and state agencies"], answer: 3, exp: "e-Trade streamlines the multi-agency documentation involved in cross-border trade, which is why it is an Integrated MMP." },
  { id: "mmp-17", topic: "itp-mmp", q: "The Digitization India Platform (DIP) is best described as:", options: ["A national framework for converting government's physical/scanned records, documents and archives into structured, reusable digital data", "A citizen-facing document wallet like DigiLocker", "A cloud hosting service exclusively for Passport Seva", "A social media platform for government announcements"], answer: 0, exp: "DIP is specifically about digitizing government's own back-office records so they become structured, reusable data — distinct from citizen-facing DigiLocker." },
  { id: "mmp-18", topic: "itp-mmp", q: "One of DigiLocker's core features, 'issued documents', refers to:", options: ["Documents a citizen scans and uploads themselves with no verification", "Official documents pushed directly into a citizen's locker by the issuing department/organization (e.g. a digitally signed certificate), carrying the same validity as the original", "Documents that can never be shared with anyone", "Only paper documents mailed to the citizen"], answer: 1, exp: "Issued documents in DigiLocker are digitally signed originals pushed by the issuing authority, distinct from self-uploaded scans." },
  { id: "mmp-19", topic: "itp-mmp", q: "The 'eSign' facility within the DigiLocker ecosystem allows a citizen to:", options: ["Physically sign a document with a pen and scan it", "Only view documents with no signing capability", "Digitally sign an electronic document online using Aadhaar-based authentication, giving it legal validity", "Delete government-issued documents permanently"], answer: 2, exp: "eSign lets a citizen apply a legally valid digital signature to an electronic document via Aadhaar-based authentication." },
  { id: "mmp-20", topic: "itp-mmp", q: "Besides officially issued documents, DigiLocker also lets a citizen:", options: ["Issue Aadhaar numbers to other citizens", "Approve other citizens' passport applications", "Access another citizen's private locker without consent", "Upload their own scanned copies of documents for personal safekeeping and easy retrieval"], answer: 3, exp: "DigiLocker's self-upload feature lets citizens store their own document scans alongside officially issued ones." },
  { id: "mmp-21", topic: "itp-mmp", q: "GI Cloud, branded 'MeghRaj', refers to:", options: ["India's Government Community Cloud strategy, built on a panel of empanelled cloud service providers for government use", "A single central government data centre with no outside providers", "A cloud service sold directly to the general public", "A private company's proprietary internal cloud"], answer: 0, exp: "MeghRaj is a Government Community Cloud strategy relying on empanelled providers, not a single data centre or public commercial offering." },
  { id: "mmp-22", topic: "itp-mmp", q: "Among GI Cloud MeghRaj's stated goals is:", options: ["Slowing down ICT service delivery to government departments", "Faster deployment of ICT-enabled services to citizens by letting departments provision infrastructure on demand rather than building their own data centres", "Preventing any department from using cloud infrastructure", "Restricting cloud use to only one specific ministry"], answer: 1, exp: "MeghRaj's core goal is enabling faster, on-demand ICT service delivery instead of each department building isolated infrastructure." },
  { id: "mmp-23", topic: "itp-mmp", q: "A key cost-related goal of GI Cloud MeghRaj is:", options: ["Maximizing the number of data centres each department must build", "Increasing costs deliberately to fund private vendors", "Optimizing government ICT spending by sharing infrastructure across departments instead of each building redundant, underutilized data centres", "Eliminating the government's IT budget entirely"], answer: 2, exp: "MeghRaj aims at cost optimization through shared infrastructure, avoiding redundant, underutilized departmental data centres." },
  { id: "mmp-24", topic: "itp-mmp", q: "GI Cloud MeghRaj helps government applications handle unpredictable demand spikes (e.g. exam result portals) primarily through:", options: ["Fixed, non-adjustable server capacity", "Requiring citizens to access services only at night", "A rule limiting each application to a single server", "Scalable cloud infrastructure that can be scaled up or down based on actual demand"], answer: 3, exp: "Cloud elasticity/scalability under MeghRaj lets applications handle demand spikes without over-provisioning fixed infrastructure." },
  { id: "mmp-25", topic: "itp-mmp", q: "Cloud service providers join the GI Cloud MeghRaj panel by:", options: ["Undergoing an empanelment process, including security audit/compliance checks, before being authorized to host government applications", "Simply registering a company name with no review", "Paying a one-time advertising fee", "Being selected at random"], answer: 0, exp: "Empanelment under MeghRaj requires providers to pass security audit and compliance checks before hosting government workloads." },
  { id: "mmp-26", topic: "itp-mmp", q: "e-Kranti, described as 'NeGP 2.0', primarily represents:", options: ["A complete abandonment of the Mission Mode Project approach", "An expansion and modernization of NeGP's MMP-based approach, incorporating cloud, mobile and a broader set of MMPs", "A private-sector-only rebranding exercise", "A program limited exclusively to defense IT"], answer: 1, exp: "e-Kranti builds on and expands NeGP's original MMP approach rather than discarding it." },
  { id: "mmp-27", topic: "itp-mmp", q: "e-Kranti's guiding design principle, 'Transformation and not Translation', means:", options: ["Simply converting an existing paper form into an identical online PDF", "Translating government forms into regional languages only, with no process change", "Redesigning government processes for genuinely improved service delivery, rather than just digitizing the old paper-based process unchanged", "Replacing government processes with entirely manual alternatives"], answer: 2, exp: "The principle calls for redesigning processes for real improvement, not merely digitizing an unchanged paper workflow." },
  { id: "mmp-28", topic: "itp-mmp", q: "Compared to NeGP's original set of Mission Mode Projects, e-Kranti's scope:", options: ["Was reduced to a single MMP", "Remained numerically and technologically identical", "Excluded all previously existing MMPs", "Was substantially expanded, adding new MMPs and emphasizing newer technologies like cloud and mobile-based delivery"], answer: 3, exp: "e-Kranti significantly broadened the MMP portfolio and pushed adoption of cloud and mobile delivery channels." },
  { id: "mmp-29", topic: "itp-mmp", q: "A newly launched service letting applicants track their passport application status online was developed and is owned by the Ministry of External Affairs. It should be classified as a:", options: ["Central MMP, since it is owned and implemented by a union ministry", "State MMP", "Integrated MMP", "Not an MMP since it only tracks status"], answer: 0, exp: "Ownership by a union ministry (External Affairs) makes this a Central MMP, regardless of the specific feature involved." },
  { id: "mmp-30", topic: "itp-mmp", q: "The correct basis for classifying an MMP as Central, State, or Integrated is:", options: ["Which level of government the citizen happens to be interacting with at that moment", "Which level(s) of government own, fund and implement the project", "The programming language used to build the application", "Whether the application has a mobile app version"], answer: 1, exp: "Classification depends on which level(s) of government own and implement the project, not incidental technical or interaction details." },
  { id: "mmp-31", topic: "itp-mmp", q: "The Passport Seva Project's public-private partnership model involves:", options: ["Complete transfer of passport-issuing authority to a private company", "No private-sector involvement whatsoever", "A private IT service provider operating Passport Seva Kendras and back-end systems under the Ministry of External Affairs' oversight, while passport issuance authority remains with the government", "A state government running the entire project independently"], answer: 2, exp: "The PPP model keeps sovereign issuance authority with government while a private partner runs the operational front-end/back-end." },
  { id: "mmp-32", topic: "itp-mmp", q: "CCTNS (Crime and Criminal Tracking Network & Systems), a Mission Mode Project connecting police stations nationwide, primarily supports:", options: ["Municipal tax collection", "Corporate registration filings", "Passport issuance", "Digitized crime records, investigation tracking and information-sharing across police stations and states"], answer: 3, exp: "CCTNS links police stations nationwide for shared crime-record and investigation data." },
  { id: "mmp-33", topic: "itp-mmp", q: "Two MMPs deliver similar citizen services (issuing certificates), but one is Central and the other State. What most likely explains the difference?", options: ["One is owned/implemented by a union ministry, the other by an individual state government", "One uses a database and the other doesn't", "One is free and the other is paid", "There is no meaningful difference between the two"], answer: 0, exp: "MMP classification tracks ownership/implementation level, not technical implementation details or cost." },
  { id: "mmp-34", topic: "itp-mmp", q: "Integrated MMPs like GST and UID/Aadhaar require coordinated implementation across levels of government primarily because:", options: ["Coordination is legally prohibited for such projects", "Their underlying data, processes or authentication needs are shared and used by both central and state agencies", "Only citizens, never any government body, use these systems", "They are entirely unrelated to any government function"], answer: 1, exp: "Shared data/process needs across central and state agencies is exactly why Integrated MMPs require coordinated implementation." },
  { id: "mmp-35", topic: "itp-mmp", q: "Documents issued through DigiLocker carry the same legal validity as their physical counterparts primarily because of:", options: ["An informal government promise with no legal basis", "A private company's internal policy", "The IT Act 2000's legal recognition of electronic records and digital signatures", "The Copyright Act 1957"], answer: 2, exp: "DigiLocker documents rely on the IT Act's recognition of electronic records/digital signatures for their legal validity." },
  { id: "mmp-36", topic: "itp-mmp", q: "A key difference between GI Cloud MeghRaj and a general-purpose commercial public cloud is:", options: ["MeghRaj has no security requirements at all", "MeghRaj can only be used by private companies, never government", "There is no difference whatsoever", "MeghRaj providers are empanelled specifically to meet government security/compliance requirements for hosting public-sector applications"], answer: 3, exp: "MeghRaj's defining feature is empanelment against government-specific security/compliance requirements." },
  { id: "mmp-37", topic: "itp-mmp", q: "Mission Mode Projects under NeGP are generally expected to be tracked against:", options: ["Clear milestones and measurable service-delivery outcomes, monitored by designated apex/oversight bodies", "No defined milestones or monitoring mechanism", "Only informal, undocumented progress updates", "A schedule set entirely by the implementing vendor with no government review"], answer: 0, exp: "NeGP's MMP approach explicitly requires milestone-based, monitored implementation, not informal or vendor-only tracking." },
  { id: "mmp-38", topic: "itp-mmp", q: "A state government builds its own online portal (using state funds and staff) to digitize property tax records for its municipalities. This is best classified as a:", options: ["Central MMP", "State MMP", "Integrated MMP", "A private commercial product"], answer: 1, exp: "State funding, ownership and implementation makes this a State MMP." },
  { id: "mmp-39", topic: "itp-mmp", q: "The Digitization India Platform's main value to Mission Mode Projects is that it:", options: ["Issues Aadhaar numbers to citizens", "Provides cloud hosting exclusively", "Lets departments reuse already-digitized government records instead of each MMP separately scanning and re-keying the same historical data", "Replaces the need for any MMP to collect new data"], answer: 2, exp: "DIP's value is enabling reuse of already-digitized records across MMPs, avoiding duplicated scanning/re-keying effort." },
  { id: "mmp-40", topic: "itp-mmp", q: "Which of the following is NOT one of the recognized Mission Mode Project categories?", options: ["Central", "State", "Integrated", "Private"], answer: 3, exp: "The three recognized MMP categories are Central, State and Integrated — there is no separate 'Private' MMP category." },
  { id: "mmp-41", topic: "itp-mmp", q: "Why is GST implemented as an Integrated MMP rather than purely a Central or State one?", options: ["Because GST replaced both central taxes (like excise) and state taxes (like VAT/commercial tax) with a single system requiring joint central-state administration", "Because GST has nothing to do with taxation", "Because only citizens interact with GSTN, not any government body", "Because GST is managed entirely by a private company with no government role"], answer: 0, exp: "GST subsumed both central and state indirect taxes, which is why its administration is jointly integrated across levels." },
  { id: "mmp-42", topic: "itp-mmp", q: "Regarding the total number of Mission Mode Projects over time, which statement is most accurate?", options: ["The number of MMPs has remained exactly fixed since NeGP's inception with no additions", "NeGP began with a defined set of MMPs across the three categories, and this set was substantially expanded when e-Kranti (NeGP 2.0) was introduced", "MMPs were reduced to zero under e-Kranti", "Only Central MMPs have ever existed, with no State or Integrated MMPs"], answer: 1, exp: "e-Kranti substantially expanded NeGP's original MMP portfolio rather than leaving it unchanged or eliminating it." },
  { id: "mmp-43", topic: "itp-mmp", q: "If a citizen uploads a scanned copy of a privately issued rent agreement to their DigiLocker, this falls under which DigiLocker feature?", options: ["Issued documents", "eSign", "Self-uploaded documents", "GI Cloud MeghRaj"], answer: 2, exp: "A privately obtained document scanned and uploaded by the citizen themself falls under DigiLocker's self-uploaded documents feature, not issued documents." },
  { id: "mmp-44", topic: "itp-mmp", q: "Which best distinguishes GI Cloud 'MeghRaj' from the Digitization India Platform (DIP)?", options: ["They are simply two different names for the exact same platform", "MeghRaj digitizes old paper records; DIP provides cloud hosting — the reverse of their actual roles", "Neither has anything to do with Mission Mode Projects", "MeghRaj provides shared cloud computing/hosting infrastructure for government applications, while DIP focuses on converting government's existing physical records into reusable digital data — they solve different problems"], answer: 3, exp: "MeghRaj is cloud infrastructure; DIP is about digitizing existing physical records — distinct, complementary roles." },
  { id: "mmp-45", topic: "itp-mmp", q: "'Banking', as one of the original Central Mission Mode Projects, focused on:", options: ["Digitizing and interconnecting banking services/infrastructure at a national level, an area the union government coordinates given banking's national regulatory framework", "Only village-level cooperative societies", "Municipal water billing", "State land record digitization"], answer: 0, exp: "Banking as a Central MMP reflects the union-level regulatory and infrastructure coordination role in national banking services." },
  { id: "mmp-46", topic: "itp-mmp", q: "The 'Pension' Mission Mode Project is categorized as Central primarily because:", options: ["Pension records are only ever handled at the municipal level", "Central government pension administration and disbursement is coordinated at the union level", "It is a private insurance product with no government role", "It is jointly and equally implemented by every state independently with no central coordination"], answer: 1, exp: "Central government pension administration is coordinated at the union level, placing this MMP in the Central category." },
  { id: "mmp-47", topic: "itp-mmp", q: "e-Procurement and e-Biz (aimed at easing business setup/compliance) are best classified as:", options: ["Central MMPs only", "State MMPs only", "Integrated MMPs, since they typically involve processes and approvals spanning multiple government levels/agencies", "Not MMPs at all"], answer: 2, exp: "Business setup/compliance processes usually cut across central and state approvals, making these Integrated MMPs." },
  { id: "mmp-48", topic: "itp-mmp", q: "The main reason Mission Mode Projects are encouraged to build on shared platforms like DIP, DigiLocker and GI Cloud MeghRaj, rather than each building separate infrastructure, is to:", options: ["Deliberately slow down project timelines", "Prevent any project from ever going live", "Restrict access to only one ministry at a time", "Avoid duplicated effort/cost and ensure faster, more consistent, interoperable service delivery across projects"], answer: 3, exp: "Shared platforms reduce duplicated effort and improve consistency/interoperability across many MMPs." },
  { id: "mmp-49", topic: "itp-mmp", q: "e-Kranti's expanded MMP framework is best understood as supporting which broader national program?", options: ["Digital India, whose 'governance and services on demand' vision area e-Kranti's expanded MMPs directly serve", "A program entirely unrelated to Digital India", "Only a state-specific Gujarat program", "A purely private-sector software marketing campaign"], answer: 0, exp: "e-Kranti's expanded MMPs directly serve Digital India's 'governance and services on demand' vision area." },
  { id: "mmp-50", topic: "itp-mmp", q: "Overall, Central, State and Integrated Mission Mode Projects, built increasingly on shared platforms like the Digitization India Platform, DigiLocker and GI Cloud MeghRaj under e-Kranti, together illustrate:", options: ["A fragmented set of unrelated government IT purchases with no common thread", "A structured national approach where individually owned, milestone-driven e-governance projects increasingly share common digital infrastructure to deliver services more efficiently and consistently", "A framework relevant only to private companies, not government", "An approach that deliberately avoids any central coordination"], answer: 1, exp: "This structured, infrastructure-sharing approach across MMP categories is the central takeaway of NeGP/e-Kranti's design." },

  // ================= E-Governance Policies & Gujarat IT/ITeS Policy 2022-27 (50) =================
  { id: "pol-01", topic: "itp-policy", q: "NeGP's implementation approach, described as 'centralized initiative, decentralized implementation', means:", options: ["Every decision, however small, must be approved by a single central office with no delegation", "Overall policy direction and standards are set at the national level, while actual project execution/ownership rests with the concerned ministry, department or state", "States have no role whatsoever in implementation", "Implementation happens with no reference to any national standards"], answer: 1, exp: "National-level direction/standards combined with state/department-level execution is the essence of this NeGP principle." },
  { id: "pol-02", topic: "itp-policy", q: "A core NeGP principle regarding project ownership is:", options: ["Only the central government may ever own any MMP", "Private companies always retain full ownership of MMPs", "MMPs are jointly owned by the central and state governments concerned, with the implementing ministry/department/state responsible for the project's success", "Ownership is deliberately left undefined for every MMP"], answer: 2, exp: "NeGP assigns clear ownership to the implementing government body, central and state governments being jointly invested in outcomes." },
  { id: "pol-03", topic: "itp-policy", q: "NeGP explicitly encourages using a public-private partnership (PPP) model:", options: ["Wherever feasible, to leverage private-sector efficiency and investment alongside government oversight in implementing e-governance projects", "Never, since NeGP prohibits any private-sector role", "Only for defense-related projects", "Only when a state specifically requests it in writing every single time"], answer: 0, exp: "NeGP treats PPP as a viable delivery model wherever it can improve efficiency, as seen in projects like Passport Seva." },
  { id: "pol-04", topic: "itp-policy", q: "The State Wide Area Network (SWAN), part of NeGP's common infrastructure, provides:", options: ["A national television broadcasting network", "A private social media platform", "A single citizen-facing mobile application", "Reliable, dedicated network connectivity linking state headquarters down to block/district level offices, supporting e-governance applications"], answer: 3, exp: "SWAN is dedicated network connectivity infrastructure enabling e-governance applications to reach down to the district/block level." },
  { id: "pol-05", topic: "itp-policy", q: "The State Data Centre (SDC), another piece of NeGP's common infrastructure, functions as:", options: ["A centralized facility hosting a state's e-governance applications and data securely, so departments don't each build separate data centres", "A citizen document wallet like DigiLocker", "A private commercial cloud sold to individuals", "A physical archive of paper files with no digital component"], answer: 0, exp: "SDCs consolidate hosting for a state's e-governance applications, avoiding duplicated departmental infrastructure." },
  { id: "pol-06", topic: "itp-policy", q: "Common Services Centres (CSC), one of NeGP's common infrastructure components, primarily serve as:", options: ["Data centres reserved exclusively for state ministers", "Last-mile physical access points (often village-level) through which citizens can access a range of e-governance and other digital services", "A private courier delivery network", "An online-only service with no physical presence"], answer: 1, exp: "CSCs are physical last-mile access points, especially important for citizens without personal digital devices/connectivity." },
  { id: "pol-07", topic: "itp-policy", q: "Digital India's three declared vision areas are:", options: ["Only expanding electronics exports, with no citizen-facing component", "Only cybersecurity, defense and foreign policy", "Digital infrastructure as a core utility, governance & services on demand, and digital empowerment of citizens", "Only promoting private e-commerce companies"], answer: 2, exp: "These three vision areas are the officially stated pillars framing the Digital India program." },
  { id: "pol-08", topic: "itp-policy", q: "Among Digital India's nine pillars is:", options: ["Restricting internet access to major cities only", "Eliminating all electronics manufacturing in India", "Banning mobile phone use in government offices", "Broadband Highways, aimed at providing high-speed digital connectivity across urban and rural India"], answer: 3, exp: "Broadband Highways is one of Digital India's nine pillars, focused on expanding high-speed connectivity nationwide." },
  { id: "pol-09", topic: "itp-policy", q: "Digital India's 'e-Kranti' pillar refers to:", options: ["The electronic delivery of services pillar, expanding Mission Mode Projects and using newer technology (cloud, mobile) for service delivery", "A pillar focused solely on foreign policy", "A pillar banning digital payments", "A pillar unrelated to any Mission Mode Project"], answer: 0, exp: "e-Kranti as a Digital India pillar is specifically about electronic service delivery through an expanded MMP framework." },
  { id: "pol-10", topic: "itp-policy", q: "Digital India's 'IT for Jobs' pillar aims to:", options: ["Eliminate IT-related employment entirely", "Train youth, particularly in smaller towns/rural areas, in IT skills to improve their employability in the IT/ITeS sector", "Only benefit graduates from a single specific city", "Focus exclusively on government employee retraining"], answer: 1, exp: "IT for Jobs targets broader IT-skill training, especially reaching beyond major metros, to improve employability." },
  { id: "pol-11", topic: "itp-policy", q: "The National Data Sharing and Accessibility Policy (NDSAP), 2012, primarily encourages:", options: ["Citizens to share their personal data with private companies with no restriction", "Complete secrecy of all government-held data", "Government departments to proactively share the non-sensitive data they hold, promoting transparency and enabling data-driven applications", "Only sharing data with foreign governments"], answer: 2, exp: "NDSAP promotes proactive, structured sharing of non-sensitive government data to support transparency and innovation." },
  { id: "pol-12", topic: "itp-policy", q: "India's Open Government Data (OGD) Platform, supported by NDSAP, is best known by which portal?", options: ["A portal accessible only to central government employees", "A private company's proprietary analytics dashboard", "A portal that only lists government job vacancies", "data.gov.in, which hosts datasets published by various government departments for public and developer access"], answer: 3, exp: "data.gov.in is India's Open Government Data portal, hosting public datasets published under the NDSAP framework." },
  { id: "pol-13", topic: "itp-policy", q: "The Gujarat IT/ITeS Policy 2022-27 is best described as:", options: ["A five-year state government policy setting out objectives and incentives to attract IT/ITeS investment and employment in Gujarat", "A central government law applicable across all of India", "A one-time grant scheme with no defined policy period", "A private industry association's internal charter"], answer: 0, exp: "The policy is a defined five-year (2022-27) state government framework of objectives and incentives specific to Gujarat." },
  { id: "pol-14", topic: "itp-policy", q: "Among the stated objectives of Gujarat's IT/ITeS Policy 2022-27 is:", options: ["Discouraging any company from setting up operations in Gujarat", "Positioning Gujarat as a preferred destination for IT/ITeS companies, Global Capability Centres, data centres and emerging-technology firms", "Restricting IT investment to government-owned companies only", "Eliminating employment generation as a policy goal"], answer: 1, exp: "Investment attraction and positioning Gujarat as a preferred IT/ITeS/GCC/data-centre hub are central policy objectives." },
  { id: "pol-15", topic: "itp-policy", q: "'Capital subsidy', one incentive category under Gujarat's IT/ITeS Policy 2022-27, refers to:", options: ["A tax charged on companies entering Gujarat", "A subsidy available only to companies outside Gujarat", "Financial support tied to a company's eligible capital investment (e.g. in infrastructure/equipment) when setting up or expanding operations in Gujarat", "A one-time registration fee waiver with no financial support"], answer: 2, exp: "Capital subsidy directly offsets a portion of a company's eligible capital investment, lowering the cost of setting up in Gujarat." },
  { id: "pol-16", topic: "itp-policy", q: "Support for GIDC/IT-park infrastructure, under the Gujarat IT/ITeS Policy 2022-27, primarily helps companies by:", options: ["Requiring companies to build their own roads and power plants", "Banning companies from using any existing IT park", "Only applying to agricultural land development", "Providing ready-built industrial/IT-park space and infrastructure so companies don't have to develop land and infrastructure from scratch"], answer: 3, exp: "GIDC/IT-park infrastructure support gives companies ready-built space, avoiding the cost/delay of developing land themselves." },
  { id: "pol-17", topic: "itp-policy", q: "Quality-certification and patent-filing support, offered under the Gujarat IT/ITeS Policy 2022-27, is aimed at:", options: ["Helping companies offset the cost of obtaining recognized quality certifications and filing patents, encouraging higher-quality, IP-protected innovation", "Preventing companies from ever filing a patent", "Only supporting foreign patent applications, not Indian ones", "Certifying employees' personal educational degrees"], answer: 0, exp: "This incentive category reduces the cost barrier to obtaining quality certifications and filing patents, encouraging IP-protected innovation." },
  { id: "pol-18", topic: "itp-policy", q: "Skill-development assistance under Gujarat's IT/ITeS Policy 2022-27 is intended to:", options: ["Replace all formal educational institutions in the state", "Help companies fund training so the local workforce has the specific skills the IT/ITeS sector needs", "Only benefit already highly experienced senior executives", "Discourage the hiring of local talent in favor of purely outside talent"], answer: 1, exp: "Skill-development assistance supports training so local talent can meet the specific needs of incoming IT/ITeS investment." },
  { id: "pol-19", topic: "itp-policy", q: "Why does the Gujarat IT/ITeS Policy 2022-27 provide special incentives specifically for data centres and Global Capability Centres (GCCs), distinct from general IT/ITeS incentives?", options: ["Because data centres and GCCs are banned everywhere else in India", "Because they require no infrastructure at all", "Because these categories typically involve much larger capital investment and are treated as strategic priorities the state especially wants to attract", "Because the policy does not actually mention data centres or GCCs"], answer: 2, exp: "Data centres and GCCs typically represent large-scale investment and employment, warranting dedicated, larger incentive categories." },
  { id: "pol-20", topic: "itp-policy", q: "The Gujarat IT/ITeS Policy 2022-27's dedicated incentives for AI/emerging-technology and cybersecurity companies reflect:", options: ["A restriction preventing AI companies from operating in Gujarat", "Incentives that apply only to companies founded before 2000", "A rule limiting cybersecurity companies to government contracts only", "A deliberate policy choice to prioritize and attract companies working in high-growth, strategically important technology areas"], answer: 3, exp: "Dedicated AI/emerging-tech and cybersecurity incentives reflect the state's strategic priority on high-growth technology sectors." },
  { id: "pol-21", topic: "itp-policy", q: "'Single-window clearance', offered under Gujarat's IT/ITeS Policy 2022-27, primarily helps investors by:", options: ["Letting them route approvals for land, power, registration and other requirements through one consolidated nodal process instead of multiple separate departments", "Eliminating the need for any government approval whatsoever", "Requiring investors to visit every department in person, one at a time", "Applying only to companies with no employees"], answer: 0, exp: "Single-window clearance consolidates multi-department approvals into one streamlined process, speeding up project setup." },
  { id: "pol-22", topic: "itp-policy", q: "Gujarat's IT/ITeS Policy 2022-27 succeeded which kind of earlier state policy framework?", options: ["There was no earlier Gujarat IT policy of any kind", "Earlier Gujarat IT/ITeS policies from previous policy periods, reflecting the state's ongoing, periodically renewed approach to attracting IT investment", "A central government policy that Gujarat simply copied verbatim", "A policy specific to only one single private company"], answer: 1, exp: "Gujarat has periodically renewed its IT/ITeS policy over successive policy periods, with 2022-27 being the current one." },
  { id: "pol-23", topic: "itp-policy", q: "Which best describes the relationship between NeGP and Digital India?", options: ["They are entirely unrelated programs from different countries", "NeGP came after and replaced Digital India", "Digital India (2015) built on and expanded NeGP's (2006) Mission Mode Project-based approach with a broader three-part vision", "Digital India abolished all Mission Mode Projects"], answer: 2, exp: "Digital India built on and broadened NeGP's original MMP-based approach rather than replacing or predating it." },
  { id: "pol-24", topic: "itp-policy", q: "A company deciding whether to set up a Global Capability Centre in Gujarat would most directly consult:", options: ["The Copyright Act 1957, since it governs where companies may locate operations", "The RTI Act 2005, since it approves investment applications", "The Aadhaar Act 2016, since it regulates corporate investment", "The Gujarat IT/ITeS Policy 2022-27, for the specific incentive categories, eligibility criteria and application process for GCCs"], answer: 3, exp: "The Gujarat IT/ITeS Policy 2022-27 is the specific instrument governing GCC-related incentives and eligibility in the state." },
  { id: "pol-25", topic: "itp-policy", q: "GIFT City (Gujarat International Finance Tec-City) is often cited as an example of a location in Gujarat that particularly benefits from IT/ITeS and financial-sector policy support because it:", options: ["Is a purpose-built business district designed to attract financial services and technology-driven companies, including GCCs, to Gujarat", "Is a purely residential township with no commercial activity", "Only exists as a name with no physical development", "Is restricted to agricultural use only"], answer: 0, exp: "GIFT City is a purpose-built financial/technology business district, a natural beneficiary of IT/ITeS and GCC-focused incentives." },
  { id: "pol-26", topic: "itp-policy", q: "A key difference between the National Data Sharing and Accessibility Policy (NDSAP) and the Digital Personal Data Protection Act (DPDP Act) is that:", options: ["They are simply two names for the same law", "NDSAP is about government proactively sharing its own non-sensitive data outward; the DPDP Act is about protecting individuals' personal data from misuse — they address different problems", "NDSAP protects personal data while the DPDP Act shares government data", "Neither policy has anything to do with data"], answer: 1, exp: "NDSAP addresses government data-sharing/openness; the DPDP Act addresses personal-data protection — distinct concerns." },
  { id: "pol-27", topic: "itp-policy", q: "Digital India's 'Public Internet Access Programme' pillar primarily focuses on:", options: ["Restricting internet access to only large corporations", "Banning the use of Common Services Centres", "Expanding public access points to the internet, including through Common Services Centres and post offices, especially in underserved areas", "Providing internet access exclusively to central government offices"], answer: 2, exp: "This pillar expands public internet access points, particularly in underserved areas, via channels like CSCs and post offices." },
  { id: "pol-28", topic: "itp-policy", q: "Digital India's 'Information for All' pillar aims to:", options: ["Restrict all government information from public access", "Apply only to information about a single ministry", "Require all information requests to be made only in person", "Make government information and documents easily and openly accessible to citizens online, including through open data and online hosting of information"], answer: 3, exp: "Information for All emphasizes open, online accessibility of government information, complementing transparency policies like NDSAP." },
  { id: "pol-29", topic: "itp-policy", q: "Why does NeGP emphasize 'common infrastructure' (like SWAN, SDC, CSC) shared across Mission Mode Projects rather than each MMP building its own?", options: ["To avoid duplicated cost/effort and ensure MMPs have reliable, consistent, interoperable infrastructure to run on", "Because common infrastructure has no benefit over isolated systems", "Because each MMP is legally prohibited from having any infrastructure", "Because it makes each MMP more expensive to build"], answer: 0, exp: "Shared common infrastructure avoids duplicated cost and ensures interoperability across the many MMPs built on it." },
  { id: "pol-30", topic: "itp-policy", q: "The Gujarat IT/ITeS Policy 2022-27's employment-generation objective is most directly supported by which incentive category?", options: ["Capital subsidy alone, with no link to employment", "Skill-development assistance, which helps prepare the local workforce for jobs the incoming IT/ITeS investment creates", "Single-window clearance, which has no connection to workforce skills", "Quality-certification support, which is unrelated to hiring"], answer: 1, exp: "Skill-development assistance most directly supports the employment-generation objective by preparing the local workforce." },
  { id: "pol-31", topic: "itp-policy", q: "Which of these would most likely NOT be covered under Gujarat's IT/ITeS Policy 2022-27's incentive structure?", options: ["A capital subsidy for an eligible IT/ITeS company's new office setup", "Special incentives for a new data centre investment", "A subsidy for a business entirely unrelated to IT/ITeS, such as a traditional textile mill with no digital component", "Skill-development support for an IT/ITeS company's new hires"], answer: 2, exp: "The policy's incentives are targeted at IT/ITeS, data-centre, GCC and related emerging-tech investment, not unrelated traditional industries." },
  { id: "pol-32", topic: "itp-policy", q: "A key rationale behind the Gujarat IT/ITeS Policy 2022-27's dedicated GCC incentive category is that GCCs:", options: ["Are legally barred from operating anywhere in India", "Have no connection to employment generation", "Are automatically ineligible for any state incentive nationwide", "Represent large-scale, high-value employment and investment opportunities that many states actively compete to attract"], answer: 3, exp: "States actively compete for GCC investment given its scale, which is why the policy carves out dedicated GCC incentives." },
  { id: "pol-33", topic: "itp-policy", q: "Which best summarizes the overall goal of Gujarat's IT/ITeS Policy 2022-27's various incentive categories, taken together?", options: ["To lower the effective cost and complexity of setting up and scaling IT/ITeS operations in Gujarat, making the state more competitive at attracting investment and jobs", "To make Gujarat the most expensive and complex place in India to set up an IT company", "To eliminate all IT/ITeS activity from the state", "To benefit only companies headquartered outside India"], answer: 0, exp: "The policy's incentives collectively aim to lower cost/complexity and make Gujarat more competitive for IT/ITeS investment." },
  { id: "pol-34", topic: "itp-policy", q: "Under NeGP's approach, who is typically accountable for the success of an individual Mission Mode Project?", options: ["No one; MMPs have no defined accountability", "The specific ministry, department or state government that owns and implements that MMP", "Only a private vendor, with the government bearing no responsibility", "Only citizens, who are expected to self-manage the project"], answer: 1, exp: "Accountability rests with the owning/implementing ministry, department or state government, consistent with NeGP's ownership principle." },
  { id: "pol-35", topic: "itp-policy", q: "Digital India's 'Electronics Manufacturing' pillar aims to:", options: ["Ban all electronics manufacturing in India", "Restrict electronics manufacturing to imports only, with no domestic production", "Promote domestic electronics manufacturing, reducing import dependence and building indigenous production capacity", "Apply exclusively to software, with no relevance to hardware"], answer: 2, exp: "This pillar promotes indigenous electronics production capacity, reducing reliance on imports." },
  { id: "pol-36", topic: "itp-policy", q: "A start-up wants to know if there is a state-level policy specifically incentivizing its plan to open a cybersecurity R&D unit in Gujarat. It should look at:", options: ["The Copyright Act 1957", "The RTI Act 2005", "The Aadhaar Act 2016", "The Gujarat IT/ITeS Policy 2022-27, which includes dedicated incentives for cybersecurity companies"], answer: 3, exp: "The Gujarat IT/ITeS Policy 2022-27 is the appropriate instrument, since it specifically incentivizes cybersecurity companies." },
  { id: "pol-37", topic: "itp-policy", q: "Which statement about NeGP's 'monitoring mechanism' principle is most accurate?", options: ["NeGP envisaged dedicated apex bodies/mechanisms to monitor MMP progress against defined milestones, supporting accountability", "NeGP explicitly prohibits any monitoring of MMP progress", "Monitoring under NeGP is left entirely to private vendors with no government role", "NeGP requires monitoring only once every ten years"], answer: 0, exp: "NeGP's design includes monitoring against defined milestones through designated apex/oversight mechanisms." },
  { id: "pol-38", topic: "itp-policy", q: "Which of these is an example of the kind of non-sensitive government data that NDSAP-driven open data platforms like data.gov.in typically publish?", options: ["Individual citizens' private medical records", "Aggregated statistical datasets such as census figures, agricultural production data, or public transport schedules", "Classified national defense intelligence", "Individual bank account passwords"], answer: 1, exp: "Open data platforms publish aggregated, non-sensitive statistical datasets, not private, classified, or credential data." },
  { id: "pol-39", topic: "itp-policy", q: "How does the Gujarat IT/ITeS Policy 2022-27 relate to national programs like Digital India?", options: ["It replaces Digital India entirely within Gujarat's borders", "It has no relationship to Digital India whatsoever", "It operates as a complementary state-level policy, directing state investment/incentives in a way that supports the same broad national digital-economy goals", "It overrides and cancels all central government IT policy"], answer: 2, exp: "State policies like Gujarat's IT/ITeS Policy work alongside, and support, the broader national Digital India goals rather than replacing them." },
  { id: "pol-40", topic: "itp-policy", q: "Which pillar of Digital India is most directly reflected in the expansion of Mission Mode Projects and adoption of cloud/mobile-based service delivery discussed under e-Kranti?", options: ["The Electronics Manufacturing pillar", "The Broadband Highways pillar", "None of Digital India's pillars relate to this", "The e-Kranti pillar itself, which is explicitly about electronic delivery of services"], answer: 3, exp: "The e-Kranti pillar is explicitly the electronic-service-delivery pillar that this expanded MMP framework belongs to." },
  { id: "pol-41", topic: "itp-policy", q: "A defining feature that separates Gujarat's IT/ITeS Policy 2022-27 from a purely regulatory law like the IT Act is that the policy:", options: ["Primarily offers incentives/support to encourage desired investment and behavior, rather than imposing legal obligations or penalties", "Imposes criminal penalties for non-compliance, exactly like the IT Act", "Has no connection whatsoever to investment or incentives", "Is a national law applicable across every state"], answer: 0, exp: "Unlike a regulatory statute, the policy works through incentives to encourage, rather than compel, particular investment behavior." },
  { id: "pol-42", topic: "itp-policy", q: "Which best explains why state-level IT policies (like Gujarat's) exist alongside national programs (like Digital India)?", options: ["States are legally barred from having any IT-related policy of their own", "States compete to attract investment/jobs within their own borders and can tailor incentives to their specific economic priorities, complementing the national policy framework", "National programs make all state-level policy entirely redundant and unnecessary", "State policies always directly contradict national programs"], answer: 1, exp: "State policies let individual states compete for investment with tailored incentives, complementing rather than duplicating national policy." },
  { id: "pol-43", topic: "itp-policy", q: "Under Gujarat's IT/ITeS Policy 2022-27, 'quality certification support' would most likely help a company that wants to:", options: ["Avoid ever being audited or certified by any body", "Register a trademark for its company logo only", "Obtain a recognized international quality/security certification (e.g. for its software development processes) to compete for larger contracts", "File for bankruptcy protection"], answer: 2, exp: "Quality-certification support helps offset the cost of pursuing recognized certifications that improve a company's competitiveness." },
  { id: "pol-44", topic: "itp-policy", q: "Which of these best illustrates the difference between NeGP's national-level policy role and Gujarat's IT/ITeS Policy 2022-27's state-level role?", options: ["They are identical documents issued by the same authority", "NeGP applies only to Gujarat, and the state policy applies to the rest of India", "Gujarat's policy legally supersedes NeGP nationwide", "NeGP sets a national e-governance framework and Mission Mode Project structure; Gujarat's policy separately incentivizes IT/ITeS investment specifically within the state, operating at a different level and for a different purpose"], answer: 3, exp: "NeGP is a national e-governance framework; Gujarat's policy is a state-level investment-incentive framework — different scope and purpose." },
  { id: "pol-45", topic: "itp-policy", q: "A company that has already received a capital subsidy under Gujarat's IT/ITeS Policy 2022-27 for its new office could also separately qualify for:", options: ["Skill-development assistance for training its new hires, since the policy's incentive categories are not mutually exclusive by default", "Nothing further, since only one incentive may ever be claimed under the entire policy", "A complete exemption from the IT Act 2000", "Automatic Aadhaar issuance for all its employees"], answer: 0, exp: "The policy's incentive categories generally are not mutually exclusive, so a company may qualify for more than one where eligible." },
  { id: "pol-46", topic: "itp-policy", q: "Which best captures why 'governance and services on demand', a Digital India vision area, is relevant to state IT/ITeS policy as well as e-governance MMPs?", options: ["The two concepts are entirely unrelated with no shared goal", "Both aim at the same underlying goal — citizens and businesses accessing services conveniently and efficiently — even though MMPs deliver government services directly and state IT policy attracts the companies/talent that build such digital services", "State IT policy replaces the need for 'services on demand' entirely", "'Services on demand' applies only to private-sector companies, never government"], answer: 1, exp: "MMPs and state investment policy both ultimately serve the same convenient, efficient service-delivery goal, from different angles." },
  { id: "pol-47", topic: "itp-policy", q: "Which of the following would be an appropriate reason for a policy analyst to review both NeGP's founding principles and Gujarat's IT/ITeS Policy 2022-27 together?", options: ["Because the two documents are legally identical and interchangeable", "Because NeGP has been repealed and replaced entirely by Gujarat's policy", "To understand how national e-governance direction (NeGP) and state-level investment incentives (Gujarat's policy) work together to shape IT project outcomes within a state like Gujarat", "Because Gujarat's policy governs cybercrime prosecution nationwide"], answer: 2, exp: "Reviewing both together clarifies how national direction and state-level incentives jointly shape a state's actual IT project outcomes." },
  { id: "pol-48", topic: "itp-policy", q: "A foreign IT company evaluating whether to expand into India, and specifically into Gujarat, would most likely consult national policy (NeGP/Digital India) for:", options: ["Nothing — national policy is irrelevant to any private company decision", "Only NeGP, since state policy has no bearing on private investment decisions", "Only Gujarat's policy, since national policy has no relevance to Gujarat", "Broad national e-governance/digital-economy direction and priorities, and Gujarat's IT/ITeS Policy 2022-27 for the specific state-level incentives and approval process"], answer: 3, exp: "A company would look at national policy for overall direction and Gujarat's policy for the specific, actionable state-level incentives." },
  { id: "pol-49", topic: "itp-policy", q: "Which best describes the overall purpose of e-governance policy instruments like NeGP, Digital India, NDSAP and Gujarat's IT/ITeS Policy 2022-27, taken together?", options: ["They collectively set direction, priorities, transparency norms and investment incentives that shape how e-governance and IT projects are planned, funded and delivered across national and state levels", "They are a random, disconnected collection of documents with no shared purpose", "They exist solely to regulate cybercrime", "They apply only to private companies, with no relevance to government projects"], answer: 0, exp: "Together these instruments set the direction, transparency norms and incentives shaping e-governance and IT project delivery nationwide and in the states." },
  { id: "pol-50", topic: "itp-policy", q: "Overall, the policy landscape spanning NeGP's founding principles, Digital India's vision, supporting policies like NDSAP, and state-level frameworks like Gujarat's IT/ITeS Policy 2022-27 illustrates:", options: ["A single, monolithic policy with no distinction between national and state roles", "A layered approach where national policy sets broad direction and transparency norms while state policy adds targeted, competitive incentives to translate that direction into actual local investment and IT projects", "A policy framework with no practical connection to real IT/ITeS investment decisions", "An approach that deliberately discourages any state-level policy innovation"], answer: 1, exp: "This layered national-direction-plus-state-incentive structure is the central takeaway of India's e-governance/IT policy landscape." },

  // ================= IT Organizations & Gujarat STI Policy (50) =================
  { id: "org-01", topic: "itp-orgs", q: "MeitY (Ministry of Electronics & Information Technology) functions as:", options: ["An industry association representing private IT companies", "The union government's nodal ministry for IT policy, e-governance programs and electronics manufacturing", "A state-level agency operating only within Gujarat", "A private testing laboratory with no government authority"], answer: 1, exp: "MeitY is the union nodal ministry driving national IT policy, e-governance programs and electronics manufacturing initiatives." },
  { id: "org-02", topic: "itp-orgs", q: "MeitY was earlier known, before being elevated to a full ministry, as:", options: ["The Ministry of Home Affairs", "The Reserve Bank of India", "The Department of Electronics and Information Technology (DeitY), functioning under a different ministry before its 2016 reorganization", "NASSCOM"], answer: 2, exp: "MeitY's predecessor was the Department of Electronics and Information Technology (DeitY) before being elevated to a full ministry." },
  { id: "org-03", topic: "itp-orgs", q: "The National Informatics Centre (NIC) primarily:", options: ["Only manufactures computer hardware for export", "Regulates private telecom companies", "Issues Aadhaar numbers to citizens", "Designs, builds and operates the IT infrastructure and network (including NICNET) that ministries, departments and states use to run their e-governance applications"], answer: 3, exp: "NIC's core role is providing the operational IT backbone/infrastructure for government e-governance systems." },
  { id: "org-04", topic: "itp-orgs", q: "NIC's network backbone connecting government offices nationwide is commonly referred to as:", options: ["NICNET", "SWAYAM", "MeghRaj", "DigiLocker"], answer: 0, exp: "NICNET is NIC's government network infrastructure, distinct from citizen-facing platforms like DigiLocker or SWAYAM." },
  { id: "org-05", topic: "itp-orgs", q: "C-DAC (Centre for Development of Advanced Computing) is primarily known for:", options: ["Issuing digital signature certificates as a Certifying Authority", "Research and development in advanced computing, including India's indigenous PARAM series of supercomputers, language technology, and cybersecurity", "Operating India's internet exchange points", "Administering the Aadhaar database"], answer: 1, exp: "C-DAC's mandate centers on advanced-computing R&D, including HPC (PARAM), language technology and cybersecurity research." },
  { id: "org-06", topic: "itp-orgs", q: "C-DAC's development of the PARAM series of supercomputers is historically significant because it:", options: ["Was purchased entirely from a foreign vendor with no domestic development", "Has no connection to computing research", "Demonstrated India's ability to indigenously build high-performance computing capability after international export restrictions on supercomputer technology", "Was a project run entirely by a private telecom company"], answer: 2, exp: "PARAM demonstrated India's ability to build supercomputing capability indigenously after facing export restrictions abroad." },
  { id: "org-07", topic: "itp-orgs", q: "STQC (Standardisation Testing and Quality Certification) primarily provides:", options: ["Aadhaar enrollment services to citizens", "Cybersecurity incident response coordination", "Domain name registration for '.in' websites", "Independent testing and certification services for IT systems/products, verifying quality, security and interoperability, often before government deployment"], answer: 3, exp: "STQC's core role is independent testing and quality/security certification of IT systems, typically before deployment." },
  { id: "org-08", topic: "itp-orgs", q: "Which body is responsible for issuing and managing the Aadhaar number under statutory authority?", options: ["UIDAI (Unique Identification Authority of India)", "NIC", "STQC", "NASSCOM"], answer: 0, exp: "UIDAI is the statutory authority responsible for issuing and managing Aadhaar numbers." },
  { id: "org-09", topic: "itp-orgs", q: "UIDAI's statutory authority to issue Aadhaar numbers was formalized through:", options: ["The IT Act, 2000, exclusively", "The Aadhaar Act, 2016, which placed UIDAI on a statutory footing after it had earlier operated under an executive notification", "The Copyright Act, 1957", "An informal understanding with no legal basis"], answer: 1, exp: "UIDAI operated under executive notification before the Aadhaar Act, 2016 gave it formal statutory authority." },
  { id: "org-10", topic: "itp-orgs", q: "CERT-In (Indian Computer Emergency Response Team) serves as India's:", options: ["National agency for issuing passports", "National agency for corporate registration", "National nodal agency for responding to cybersecurity incidents", "National agency for land record digitization"], answer: 2, exp: "CERT-In is India's national nodal agency for cybersecurity incident response, detailed further in the Cyber Security unit." },
  { id: "org-11", topic: "itp-orgs", q: "Which of the following best distinguishes STQC from CERT-In?", options: ["They are simply two different names for the exact same organization", "STQC handles incident response and CERT-In handles pre-deployment testing — the reverse of their actual roles", "Neither organization has any role in IT security", "STQC focuses on testing/certifying IT systems for quality and security before deployment, while CERT-In focuses on responding to cybersecurity incidents after they occur"], answer: 3, exp: "STQC's role is pre-deployment testing/certification; CERT-In's role is post-incident cybersecurity response — complementary, not identical." },
  { id: "org-12", topic: "itp-orgs", q: "NIXI (National Internet Exchange of India) is primarily responsible for:", options: ["Operating internet exchange points to keep domestic internet traffic within India, and managing the '.in' domain registry", "Issuing digital signature certificates", "Testing government software for quality", "Administering the Aadhaar Act"], answer: 0, exp: "NIXI operates internet exchange points and manages the '.in' domain registry, keeping domestic traffic within India." },
  { id: "org-13", topic: "itp-orgs", q: "Digital India Corporation (formerly Media Lab Asia) functions as:", options: ["A private venture capital fund with no government affiliation", "A Section 8 (not-for-profit) company under MeitY that drives specific Digital India programs and digital innovation initiatives", "A state government department in Gujarat", "The certifying authority that issues Aadhaar numbers"], answer: 1, exp: "Digital India Corporation is a not-for-profit company under MeitY driving specific Digital India programs and innovation efforts." },
  { id: "org-14", topic: "itp-orgs", q: "NASSCOM (National Association of Software and Service Companies) is best classified as:", options: ["A ministry of the union government", "A statutory regulator with powers to certify government IT systems", "An industry association representing private IT/software companies, not a government body", "A Gujarat state government department"], answer: 2, exp: "NASSCOM is a private-sector industry association, not a government ministry, regulator or department." },
  { id: "org-15", topic: "itp-orgs", q: "Which of the following is a government body, as opposed to a private industry association?", options: ["NASSCOM", "GESIA", "A private IT company", "NIC (National Informatics Centre)"], answer: 3, exp: "NIC is a government body under MeitY; NASSCOM and GESIA are industry associations, not government bodies." },
  { id: "org-16", topic: "itp-orgs", q: "Gujarat Informatics Limited (GIL) functions as:", options: ["Gujarat's nodal state agency for IT-enabled services, implementing e-governance projects and infrastructure for the state — the state counterpart of NIC", "A private company with no state government ownership or oversight", "The union government's cybersecurity incident-response agency", "An industry body representing private IT companies in Gujarat"], answer: 0, exp: "GIL is Gujarat's own nodal IT-services agency, serving a role for the state analogous to NIC's role at the union level." },
  { id: "org-17", topic: "itp-orgs", q: "Within Gujarat's state government structure, IT/S&T policy-making is primarily overseen by:", options: ["The Ministry of External Affairs", "The Department of Science & Technology, Gujarat", "NASSCOM", "CERT-In"], answer: 1, exp: "The Department of Science & Technology, Gujarat is the state department overseeing IT/S&T policy for the state." },
  { id: "org-18", topic: "itp-orgs", q: "GESIA is best described as:", options: ["A Gujarat state government department", "The Gujarat counterpart of UIDAI", "An industry association representing Gujarat's IT/ITeS companies, distinct from any government body", "A certifying authority for digital signatures"], answer: 2, exp: "GESIA (Gujarat Electronics and Software Industries Association) is a private industry association, not a government department or authority." },
  { id: "org-19", topic: "itp-orgs", q: "Which best distinguishes GIL from GESIA?", options: ["They are simply two names for the same organization", "GESIA is a government agency and GIL is a private association — the reverse of their actual roles", "Neither has any connection to Gujarat's IT sector", "GIL is a Gujarat state government agency implementing e-governance projects; GESIA is a private industry association representing IT/ITeS companies — one is government, the other is not"], answer: 3, exp: "GIL is a government agency; GESIA is a private industry association — a fundamental distinction in their nature and role." },
  { id: "org-20", topic: "itp-orgs", q: "Among the stated objectives of Gujarat's Science, Technology and Innovation (STI) Policy is:", options: ["Strengthening the state's R&D ecosystem and promoting startups, innovation and industry-academia linkages", "Discouraging any research and development activity in the state", "Restricting universities from collaborating with industry", "Eliminating all state funding for startups"], answer: 0, exp: "The STI Policy's core objectives include strengthening R&D, encouraging startups/innovation and deepening industry-academia linkages." },
  { id: "org-21", topic: "itp-orgs", q: "Gujarat's STI Policy places particular emphasis on:", options: ["Banning the use of any technology developed after 2000", "Emerging-technology focus areas, encouraging research and enterprise activity in fields expected to shape future economic growth", "Restricting research funding to only agricultural topics", "Eliminating industry-academia collaboration entirely"], answer: 1, exp: "The STI Policy prioritizes emerging-technology focus areas as part of its innovation and R&D strategy." },
  { id: "org-22", topic: "itp-orgs", q: "Gujarat's Student Startup and Innovation Policy (SSIP) reflects the broader STI ecosystem's goal of:", options: ["Preventing students from pursuing any entrepreneurial activity", "Only supporting startups founded outside Gujarat", "Encouraging and supporting student-led innovation and entrepreneurship, often through funding, mentorship and incubation support", "Replacing the need for any university education"], answer: 2, exp: "SSIP supports student-led innovation and entrepreneurship through funding, mentorship and incubation, aligned with the STI ecosystem's goals." },
  { id: "org-23", topic: "itp-orgs", q: "Industry-academia linkage, a goal under Gujarat's STI Policy, is meant to:", options: ["Keep universities and industry completely separate with no interaction", "Apply only to a single university in the state", "Prevent any research funding from reaching universities", "Connect universities/research institutions with industry so research outcomes translate more effectively into real-world products, services and startups"], answer: 3, exp: "Industry-academia linkage aims to translate research more effectively into practical, real-world outcomes." },
  { id: "org-24", topic: "itp-orgs", q: "Which best distinguishes the Gujarat STI Policy from the Gujarat IT/ITeS Policy 2022-27?", options: ["The STI Policy focuses on strengthening R&D, innovation and the startup ecosystem broadly (across sectors), while the IT/ITeS Policy specifically incentivizes IT/ITeS investment, employment and infrastructure", "They are simply two names for the exact same policy document", "The STI Policy only covers IT/ITeS companies, identical in scope to the IT/ITeS Policy", "Neither policy has anything to do with Gujarat's economy"], answer: 0, exp: "The STI Policy has a broad, cross-sector R&D/innovation focus, while the IT/ITeS Policy specifically targets IT/ITeS investment and jobs." },
  { id: "org-25", topic: "itp-orgs", q: "A government department planning to launch a new e-governance application in Gujarat would typically approach GIL for:", options: ["Cybercrime investigation, since that is GIL's core function", "Implementation support, hosting and IT infrastructure for the application, given GIL's role as the state's nodal e-governance agency", "Issuing Aadhaar numbers to citizens", "Drafting national IT legislation"], answer: 1, exp: "GIL provides implementation support and infrastructure for Gujarat's e-governance projects as the state's nodal IT agency." },
  { id: "org-26", topic: "itp-orgs", q: "Before a new government IT application goes live, which organization would most likely be approached to independently test and certify its quality/security?", options: ["NASSCOM", "GESIA", "STQC", "Digital India Corporation"], answer: 2, exp: "STQC is the organization mandated to independently test and certify IT systems' quality and security before deployment." },
  { id: "org-27", topic: "itp-orgs", q: "If a government department in Gujarat suffers a cybersecurity incident (e.g. a data breach), which national body would be the appropriate nodal point of contact for incident response coordination?", options: ["STQC", "NASSCOM", "NIXI", "CERT-In"], answer: 3, exp: "CERT-In is India's national nodal agency specifically responsible for coordinating cybersecurity incident response." },
  { id: "org-28", topic: "itp-orgs", q: "Which organization operates internet exchange points and manages India's '.in' domain registry?", options: ["NIXI", "C-DAC", "UIDAI", "GIL"], answer: 0, exp: "NIXI is specifically responsible for internet exchange point operation and the '.in' domain registry." },
  { id: "org-29", topic: "itp-orgs", q: "Which of the following best fits the description 'a Section 8 not-for-profit company under MeitY driving specific Digital India programs and innovation initiatives'?", options: ["NASSCOM", "Digital India Corporation", "GESIA", "UIDAI"], answer: 1, exp: "Digital India Corporation is the Section 8 not-for-profit company under MeitY that fits this description." },
  { id: "org-30", topic: "itp-orgs", q: "A private software company wanting to network with peers, advocate for favorable IT policy, or benchmark industry practices would most likely turn to:", options: ["UIDAI, since it regulates all private companies", "STQC, since it handles industry networking", "An industry association such as NASSCOM (nationally) or GESIA (in Gujarat)", "CERT-In, since it manages business associations"], answer: 2, exp: "Industry associations like NASSCOM and GESIA are the appropriate bodies for networking, advocacy and industry benchmarking." },
  { id: "org-31", topic: "itp-orgs", q: "Which best explains why C-DAC and NIC, though both government IT bodies, are not interchangeable?", options: ["They are simply two names for the same organization", "C-DAC runs government applications while NIC does pure research — the reverse of their actual roles", "Neither organization is involved in any government IT function", "C-DAC's core mandate is advanced-computing research and development, while NIC's core mandate is operating IT infrastructure/services that run government applications"], answer: 3, exp: "C-DAC focuses on R&D, while NIC focuses on operational IT infrastructure/services — distinct, complementary mandates." },
  { id: "org-32", topic: "itp-orgs", q: "A state's e-governance project relying on Aadhaar-based authentication for beneficiary verification would primarily interface with:", options: ["UIDAI's authentication APIs", "NIXI's domain registry", "GESIA's membership directory", "C-DAC's supercomputing cluster"], answer: 0, exp: "Aadhaar-based authentication is performed through UIDAI's authentication infrastructure/APIs, not the other listed bodies." },
  { id: "org-33", topic: "itp-orgs", q: "Which best describes the overall relationship between MeitY and bodies like NIC, C-DAC, STQC and UIDAI?", options: ["They are entirely independent bodies with no policy relationship to MeitY whatsoever", "MeitY is the nodal ministry setting overall IT policy direction, while NIC, C-DAC, STQC and UIDAI are specialized bodies/agencies that operate under or alongside it (or, for UIDAI, under its own statute) to implement specific functions", "NIC, C-DAC, STQC and UIDAI collectively set policy that MeitY must follow", "MeitY is a private company with no government authority"], answer: 1, exp: "MeitY sets overall policy direction, while these specialized bodies implement distinct functions under or alongside it." },
  { id: "org-34", topic: "itp-orgs", q: "Gujarat's counterpart to the union government's NIC, in terms of implementing state e-governance infrastructure, is:", options: ["GESIA", "Department of Science & Technology, Gujarat", "GIL (Gujarat Informatics Limited)", "NASSCOM"], answer: 2, exp: "GIL is Gujarat's implementation-focused nodal e-governance agency, functionally analogous to NIC at the union level." },
  { id: "org-35", topic: "itp-orgs", q: "Which of these government/industry bodies would be inappropriate to approach for help drafting or reviewing a company's own internal cybersecurity policy — because it is not a cybersecurity-focused organization?", options: ["CERT-In, which handles incident response and advisories", "STQC, which can test/certify security of systems", "C-DAC, which has cybersecurity R&D expertise", "NIXI, whose mandate is internet exchange operation and domain registry management, not cybersecurity advisory"], answer: 3, exp: "NIXI's mandate is internet exchange/domain registry operation, not cybersecurity advisory, unlike CERT-In, STQC or C-DAC." },
  { id: "org-36", topic: "itp-orgs", q: "Which of these organizations was established specifically to provide India's IT backbone for running government e-governance applications, well before Digital India or NeGP existed?", options: ["NIC, established in 1976, predating most later e-governance programs", "UIDAI, established only after the Aadhaar Act 2016", "Digital India Corporation, established as part of Digital India in 2015", "GESIA, a private industry body with no government role"], answer: 0, exp: "NIC's establishment in 1976 predates NeGP (2006) and Digital India (2015) by decades." },
  { id: "org-37", topic: "itp-orgs", q: "Which best explains why NASSCOM and GESIA, despite not being government bodies, are still relevant to India's/Gujarat's IT ecosystem?", options: ["They have full statutory authority to issue government regulations", "As industry associations, they represent private-sector interests, facilitate networking/advocacy, and often collaborate with government on skilling, policy feedback and industry events", "They replace the need for any government IT body", "They have no relevance to the IT ecosystem at all"], answer: 1, exp: "Industry associations play a meaningful role through advocacy, networking and government collaboration, even without statutory authority." },
  { id: "org-38", topic: "itp-orgs", q: "Under the Gujarat STI Policy, funding/support directed toward 'emerging-technology focus areas' would most likely apply to a startup working on:", options: ["A traditional handwritten ledger-keeping service with no technology component", "A business explicitly excluded from any state innovation support", "An artificial intelligence-based diagnostic tool, since AI is typically treated as an emerging-technology priority area", "An activity unrelated to research, technology or innovation"], answer: 2, exp: "AI-based innovation typically falls squarely within the kind of emerging-technology focus areas the STI Policy prioritizes." },
  { id: "org-39", topic: "itp-orgs", q: "Which best captures the difference in scope between MeitY and GIL?", options: ["They have identical, overlapping national jurisdiction", "GIL has authority over all of India, while MeitY is limited to Gujarat", "Neither organization has any defined jurisdiction", "MeitY is the union government's nodal IT ministry with national jurisdiction; GIL is a Gujarat state government agency with jurisdiction limited to implementing IT/e-governance for that state"], answer: 3, exp: "MeitY operates at the national level, while GIL's jurisdiction is limited to implementing IT/e-governance within Gujarat." },
  { id: "org-40", topic: "itp-orgs", q: "Which of these best represents a 'quality assurance/testing' function among India's IT organizations?", options: ["STQC testing and certifying a new e-governance application before it is deployed", "NASSCOM hosting an industry networking event", "NIXI registering a new '.in' domain", "GESIA publishing an industry newsletter"], answer: 0, exp: "STQC's testing/certification of a new application before deployment is the clearest example of a quality-assurance function here." },
  { id: "org-41", topic: "itp-orgs", q: "A researcher wanting to collaborate on India's high-performance computing (supercomputing) capability would most likely approach:", options: ["NIXI", "C-DAC", "GESIA", "CERT-In"], answer: 1, exp: "C-DAC's core mandate includes high-performance computing R&D, including the PARAM supercomputer series." },
  { id: "org-42", topic: "itp-orgs", q: "Which best describes the overall structure of union-level IT organizations described in this topic?", options: ["All these organizations perform an identical, interchangeable function", "None of these organizations report to or coordinate with MeitY in any way", "A nodal ministry (MeitY) sets policy direction, while specialized bodies beneath or alongside it (NIC, C-DAC, STQC, UIDAI, CERT-In, NIXI, Digital India Corporation) each handle a distinct function — infrastructure, R&D, certification, identity, incident response, internet governance, and innovation programs respectively", "Only NASSCOM oversees all of these bodies"], answer: 2, exp: "This layered structure — nodal ministry plus specialized bodies with distinct functions — accurately reflects how union IT organizations relate to MeitY." },
  { id: "org-43", topic: "itp-orgs", q: "Which best describes the overall structure of Gujarat's state-level IT ecosystem described in this topic?", options: ["GIL and GESIA are simply the same organization under two different names", "The Department of Science & Technology has no role in Gujarat's IT ecosystem", "GESIA is a government department with statutory implementation authority", "A state policy department (Science & Technology) sets direction, GIL implements state e-governance projects and infrastructure, and GESIA represents the private IT/ITeS industry — government and industry bodies working alongside, not in place of, each other"], answer: 3, exp: "This layered structure — policy department, implementation agency, and industry association — accurately reflects Gujarat's IT ecosystem." },
  { id: "org-44", topic: "itp-orgs", q: "Which body would a Gujarat-based IT startup most likely approach for support/funding specifically framed around research, innovation and industry-academia collaboration, as opposed to IT/ITeS investment incentives generally?", options: ["Programs under the Gujarat STI Policy", "CERT-In, since it funds startups", "NIXI, since it manages startup funding", "The Copyright Act, since it funds startups"], answer: 0, exp: "The STI Policy is specifically framed around R&D, innovation and industry-academia collaboration, unlike the other listed options." },
  { id: "org-45", topic: "itp-orgs", q: "A key reason GPSC-style exams distinguish between 'government bodies' (MeitY, NIC, UIDAI, GIL) and 'industry associations' (NASSCOM, GESIA) is that:", options: ["There is no meaningful distinction between the two categories", "Government bodies have statutory/administrative authority and public accountability, while industry associations represent private-sector interests without government regulatory power", "Industry associations always have greater legal authority than government bodies", "Government bodies are always privately funded, like industry associations"], answer: 1, exp: "Government bodies carry statutory/administrative authority and public accountability, distinct from private industry associations." },
  { id: "org-46", topic: "itp-orgs", q: "Which of these correctly pairs an organization with its primary function?", options: ["NIXI — issuing Aadhaar numbers", "C-DAC — operating internet exchange points", "STQC — quality testing and certification of IT systems", "UIDAI — supercomputing research"], answer: 2, exp: "STQC's primary function is quality testing and certification of IT systems; the other pairings in this question are swapped incorrectly." },
  { id: "org-47", topic: "itp-orgs", q: "Which of these correctly pairs an organization with its primary function?", options: ["GESIA — issuing digital signature certificates", "CERT-In — running the government's cloud infrastructure", "NASSCOM — statutory regulation of all IT companies", "NIC — providing IT infrastructure/services that run government e-governance applications"], answer: 3, exp: "NIC's primary function is providing the IT infrastructure/services that run government e-governance applications." },
  { id: "org-48", topic: "itp-orgs", q: "Which of these correctly pairs a Gujarat body with its primary role?", options: ["GIL — implementing e-governance projects and infrastructure for the Gujarat state government", "GESIA — a Gujarat state government ministry", "Department of Science & Technology, Gujarat — a private industry association", "GIL — a national-level ministry with authority over all states"], answer: 0, exp: "GIL's primary role is implementing e-governance projects/infrastructure for Gujarat; the other pairings here mislabel each body's nature." },
  { id: "org-49", topic: "itp-orgs", q: "Overall, MeitY, NIC, C-DAC, STQC, UIDAI, CERT-In, NIXI and Digital India Corporation at the union level, alongside GIL, the Department of Science & Technology and GESIA in Gujarat, together illustrate:", options: ["A single monolithic organization with no functional distinction between bodies", "A layered ecosystem of specialized government bodies (policy, infrastructure, R&D, certification, identity, security, internet governance) and industry associations working at both national and state levels to plan, build, certify and support India's IT projects", "A purely private-sector ecosystem with no government involvement", "An ecosystem limited entirely to one state with no national-level bodies"], answer: 1, exp: "This layered ecosystem of specialized government bodies and industry associations, spanning national and state levels, is the central takeaway." },
  { id: "org-50", topic: "itp-orgs", q: "Which best summarizes why understanding the distinct roles of these organizations matters for someone studying IT projects and governance?", options: ["These roles have no practical relevance to real e-governance projects", "Only one of these organizations is ever relevant in practice", "Knowing which organization is responsible for which function (policy, infrastructure, R&D, certification, identity, incident response, industry representation) clarifies who to approach, what to expect, and how accountability is structured in a real e-governance project", "These organizations' roles are entirely interchangeable with no distinction"], answer: 2, exp: "Clear knowledge of each organization's function clarifies accountability and the right point of contact in real e-governance projects." },

  // ================= Legislative Framework for IT in India (50) =================
  { id: "leg-01", topic: "itp-legal", q: "The IT Act, 2000 primarily gives legal recognition to:", options: ["Only handwritten paper signatures, not any electronic form", "Electronic records and digital signatures, so an electronic document/signature can carry the same legal weight as its paper counterpart", "Criminal defamation exclusively", "Trademark registration for company logos"], answer: 1, exp: "The IT Act's foundational civil/commercial contribution is legal recognition of electronic records and digital signatures." },
  { id: "leg-02", topic: "itp-legal", q: "The IT Act, 2000 was substantially modeled on:", options: ["The Indian Penal Code exclusively", "A purely domestic framework with no reference to any international model", "The UNCITRAL Model Law on Electronic Commerce, an internationally recognized template for e-commerce/electronic-transaction legislation", "The Aadhaar Act, which came many years later"], answer: 2, exp: "The IT Act drew heavily on the UNCITRAL Model Law on Electronic Commerce, a widely referenced international template." },
  { id: "leg-03", topic: "itp-legal", q: "Under the IT Act, 2000, a valid electronic contract (e-contract) is best understood as:", options: ["A contract that is automatically invalid because it was never signed on paper", "Only a contract signed by a government official", "A type of contract that requires no consideration or agreement between parties", "An agreement formed and concluded through electronic means, which the Act treats as legally valid provided the general requirements of a valid contract are met"], answer: 3, exp: "The IT Act enables e-contracts formed through electronic means to be legally valid, provided ordinary contract requirements are satisfied." },
  { id: "leg-04", topic: "itp-legal", q: "Section 79 of the IT Act, 2000, dealing with intermediary due diligence, generally provides that:", options: ["An online intermediary (like a platform hosting user content) is not liable for third-party content if it observes the due-diligence obligations prescribed under the Act/rules", "Every intermediary is automatically liable for all user-generated content with no exceptions", "Intermediaries have no obligations whatsoever, regardless of what content they host", "Only government-owned platforms qualify as intermediaries"], answer: 0, exp: "Section 79 provides a conditional safe harbor for intermediaries that meet due-diligence obligations, not a blanket exemption or blanket liability." },
  { id: "leg-05", topic: "itp-legal", q: "The Controller of Certifying Authorities (CCA), established under the IT Act, 2000, is responsible for:", options: ["Issuing Aadhaar numbers directly to citizens", "Regulating and licensing Certifying Authorities that issue digital signature certificates, forming the backbone of India's digital-signature trust infrastructure", "Prosecuting cybercrime cases in court", "Registering copyrights for software"], answer: 1, exp: "The CCA regulates/licenses Certifying Authorities, underpinning the trust infrastructure for India's digital signature system." },
  { id: "leg-06", topic: "itp-legal", q: "The IT (Amendment) Act, 2008 broadened the IT Act's original 'digital signature' concept into the more technology-neutral term:", options: ["'Handwritten signature', reversing the shift to electronic authentication entirely", "'Biometric password', a term the Act never actually uses", "'Electronic signature', accommodating authentication technologies beyond a single specific digital-signature method", "'Aadhaar signature', tying authentication exclusively to Aadhaar"], answer: 2, exp: "The 2008 amendment introduced the broader, technology-neutral term 'electronic signature' alongside 'digital signature'." },
  { id: "leg-07", topic: "itp-legal", q: "Which best describes the civil/commercial focus of the IT Act, 2000 as distinct from its cybercrime provisions (covered separately under the Cyber Security unit)?", options: ["The civil/commercial provisions define criminal penalties for hacking and identity theft", "The civil/commercial provisions are identical in content to the cybercrime provisions", "The IT Act has no civil or commercial provisions at all", "The civil/commercial provisions establish the legal validity of electronic records, digital/electronic signatures, e-contracts, and the regulatory structure for Certifying Authorities — the foundation for lawful digital transactions"], answer: 3, exp: "The IT Act's civil/commercial provisions establish the legal foundation for digital transactions, distinct from its separately-covered cybercrime sections." },
  { id: "leg-08", topic: "itp-legal", q: "Digital signature certificates in India are issued by:", options: ["Licensed Certifying Authorities, operating under the Controller of Certifying Authorities' regulatory oversight established by the IT Act, 2000", "Any private individual with no licensing requirement", "UIDAI exclusively", "The Copyright Office"], answer: 0, exp: "Licensed Certifying Authorities issue digital signature certificates under CCA oversight, not UIDAI or the Copyright Office." },
  { id: "leg-09", topic: "itp-legal", q: "The Digital Personal Data Protection (DPDP) Act, 2023 is best described as:", options: ["A law that applies exclusively to Aadhaar-related data", "India's comprehensive law governing how personal data may be processed, centered on consent-based processing and defined obligations for entities handling that data", "An amendment to the Copyright Act, 1957", "A state-specific law applicable only in Gujarat"], answer: 1, exp: "The DPDP Act is India's comprehensive, nationwide personal-data-protection law, not limited to Aadhaar data or a single state." },
  { id: "leg-10", topic: "itp-legal", q: "Under the DPDP Act, 2023, the individual whose personal data is being processed is referred to as the:", options: ["Data Fiduciary", "Controller of Certifying Authorities", "Data Principal", "Data Protection Board"], answer: 2, exp: "The individual whose data is processed is termed the Data Principal; the Data Fiduciary is the entity processing that data." },
  { id: "leg-11", topic: "itp-legal", q: "Under the DPDP Act, 2023, the entity that determines the purpose and means of processing personal data, and bears corresponding obligations, is called the:", options: ["Data Principal", "Controller of Certifying Authorities", "Information Commission", "Data Fiduciary"], answer: 3, exp: "The Data Fiduciary determines the purpose/means of processing and carries obligations toward the Data Principal." },
  { id: "leg-12", topic: "itp-legal", q: "The DPDP Act, 2023 establishes which body to handle enforcement and grievances related to personal data protection?", options: ["The Data Protection Board of India", "The Controller of Certifying Authorities", "UIDAI", "The Central Information Commission"], answer: 0, exp: "The Data Protection Board of India is the dedicated enforcement/grievance body created under the DPDP Act." },
  { id: "leg-13", topic: "itp-legal", q: "Under the DPDP Act, 2023, lawful processing of an individual's personal data generally requires:", options: ["No basis whatsoever; any entity may process any personal data freely", "The individual's (Data Principal's) consent, or another legally recognized basis specified under the Act", "Prior approval from the Copyright Office", "Registration under the Aadhaar Act specifically"], answer: 1, exp: "The DPDP Act requires consent, or another lawful basis defined under the Act, before personal data may be processed." },
  { id: "leg-14", topic: "itp-legal", q: "A 'Significant Data Fiduciary' under the DPDP Act, 2023 refers to:", options: ["Any entity that has never processed any personal data", "A term with no defined meaning under the Act", "A category of data fiduciary designated for additional obligations, typically based on factors like the volume/sensitivity of personal data it processes", "Only entities located outside India"], answer: 2, exp: "Significant Data Fiduciary is a designated category carrying additional obligations, based on factors such as data volume/sensitivity." },
  { id: "leg-15", topic: "itp-legal", q: "Which best distinguishes the DPDP Act, 2023 from the IT Act, 2000's earlier data-related provisions?", options: ["The DPDP Act is simply a renamed section of the IT Act with no substantive difference", "The IT Act's data provisions are more comprehensive than the DPDP Act", "The two laws address completely unrelated subject matter with no overlap", "The DPDP Act is a dedicated, comprehensive data-protection law with its own consent framework and Data Protection Board, going well beyond the narrower data-related provisions that existed within the IT Act"], answer: 3, exp: "The DPDP Act is a much more comprehensive, dedicated data-protection statute compared to the IT Act's narrower earlier provisions." },
  { id: "leg-16", topic: "itp-legal", q: "The Aadhaar Act, 2016's full formal title reflects its purpose of:", options: ["Targeted delivery of financial and other subsidies, benefits and services to individuals, using Aadhaar-based authentication", "General data protection covering all types of personal data", "Software copyright protection", "Regulating internet domain names"], answer: 0, exp: "The Aadhaar Act's full title centers on targeted delivery of subsidies, benefits and services via Aadhaar authentication." },
  { id: "leg-17", topic: "itp-legal", q: "UIDAI's authority to issue and manage Aadhaar numbers was placed on a statutory footing by:", options: ["The IT Act, 2000", "The Aadhaar Act, 2016", "The Copyright Act, 1957", "The RTI Act, 2005"], answer: 1, exp: "The Aadhaar Act, 2016 gave UIDAI its statutory authority, replacing its earlier executive-notification basis." },
  { id: "leg-18", topic: "itp-legal", q: "Section 7 of the Aadhaar Act, 2016 specifically enables:", options: ["Criminal prosecution for cybercrime", "Copyright registration for software", "The use of Aadhaar-based authentication as a condition for receiving certain government subsidies, benefits or services", "Filing Right to Information requests"], answer: 2, exp: "Section 7 is the specific provision enabling Aadhaar-based authentication for targeted delivery of subsidies/benefits/services." },
  { id: "leg-19", topic: "itp-legal", q: "Which best describes the scope of the Aadhaar Act, 2016 relative to general personal-data protection?", options: ["The Aadhaar Act fully replaces the need for any separate data-protection law", "The Aadhaar Act and the DPDP Act cover identical, fully overlapping subject matter", "The Aadhaar Act has no connection whatsoever to personal data", "The Aadhaar Act governs the Aadhaar/UID system and its use for targeted benefit delivery specifically — it does not, by itself, regulate personal-data processing generally, which is the DPDP Act's role"], answer: 3, exp: "The Aadhaar Act is specific to the UID system and targeted benefit delivery, not a substitute for the DPDP Act's general data-protection role." },
  { id: "leg-20", topic: "itp-legal", q: "Computer software/source code in India is generally protected under:", options: ["The Copyright Act, 1957, which treats it as a 'literary work'", "The Aadhaar Act, 2016", "The RTI Act, 2005", "No law protects software in India"], answer: 0, exp: "The Copyright Act, 1957 treats computer software/source code as a literary work, giving it copyright protection." },
  { id: "leg-21", topic: "itp-legal", q: "Copyright protection for an original work (including software) under the Copyright Act, 1957 generally:", options: ["Only exists if the work is formally registered, with no automatic protection whatsoever", "Arises automatically upon creation of the work, though registration can provide useful evidentiary benefits in disputes", "Requires prior government approval before the software may even be written", "Applies only to works created by government employees"], answer: 1, exp: "Copyright protection arises automatically upon creation; formal registration is optional but useful evidentiary support in disputes." },
  { id: "leg-22", topic: "itp-legal", q: "Under Indian copyright law, unauthorized copying of a company's proprietary software source code by a competitor would primarily raise concerns under:", options: ["The Aadhaar Act, 2016, which has no bearing on software copying", "The RTI Act, 2005, which concerns information requests, not IP infringement", "The Copyright Act, 1957, since the source code is protected as a literary work", "No Indian law addresses this situation"], answer: 2, exp: "Copying proprietary source code is primarily a Copyright Act concern, since source code is protected as a literary work." },
  { id: "leg-23", topic: "itp-legal", q: "The Right to Information (RTI) Act, 2005 primarily gives citizens:", options: ["A right to demand free government services with no application process", "A right to access other citizens' private personal data freely", "A right that applies only to central government ministries, never state bodies", "A legal right to request and receive information from public authorities, subject to defined exemptions and response timelines"], answer: 3, exp: "The RTI Act gives citizens a legal right to information from public authorities, subject to defined exemptions and timelines." },
  { id: "leg-24", topic: "itp-legal", q: "Under the RTI Act, 2005, a public authority is generally required to respond to an information request within:", options: ["A defined statutory time limit (with a shorter timeline where the information concerns a person's life or liberty)", "No time limit whatsoever; a response may be given at the authority's convenience", "Exactly one year from the date of filing, with no exceptions", "Only if the requester is a government employee"], answer: 0, exp: "RTI has a defined statutory response timeline, with an even shorter timeline for information concerning life or liberty." },
  { id: "leg-25", topic: "itp-legal", q: "Appeals or complaints regarding an unsatisfied RTI request are generally handled by:", options: ["The Controller of Certifying Authorities", "Central or State Information Commissions, as applicable", "UIDAI", "The Data Protection Board of India"], answer: 1, exp: "Information Commissions (Central or State) are the appellate/complaint bodies under the RTI Act." },
  { id: "leg-26", topic: "itp-legal", q: "How does the RTI Act, 2005 connect to e-governance's transparency goals?", options: ["It has no connection to e-governance whatsoever", "It replaces the need for any e-governance service delivery", "It gives citizens a formal legal channel to hold public authorities accountable, and RTI requests/responses are increasingly filed and tracked digitally, reinforcing e-governance's transparency objectives", "It only applies to information about private companies, never government"], answer: 2, exp: "RTI reinforces e-governance transparency by giving citizens a formal accountability channel, increasingly delivered through digital portals." },
  { id: "leg-27", topic: "itp-legal", q: "Which best distinguishes the RTI Act, 2005 from the DPDP Act, 2023?", options: ["They are simply two names for the same law", "The RTI Act protects personal data while the DPDP Act grants access to public information — the reverse of their actual roles", "Neither law has any relevance to e-governance", "The RTI Act is about a citizen's right to obtain information from public authorities; the DPDP Act is about protecting an individual's personal data from misuse — the two address different, sometimes competing, interests (transparency versus privacy)"], answer: 3, exp: "RTI advances transparency/disclosure, while the DPDP Act advances privacy/data protection — related but distinct, sometimes competing, goals." },
  { id: "leg-28", topic: "itp-legal", q: "A fintech app performing Aadhaar-based eKYC (electronic Know Your Customer) to open a new account would rely on which combination of laws for its core operation?", options: ["The IT Act (legal validity of the electronic record/process), the Aadhaar Act (legal basis for Aadhaar-based authentication), and the DPDP Act (consent and data-handling obligations)", "Only the Copyright Act, with no other law relevant", "Only the RTI Act, with no other law relevant", "No law applies to this scenario"], answer: 0, exp: "A real-world eKYC flow typically depends jointly on the IT Act, Aadhaar Act and DPDP Act, each governing a different aspect." },
  { id: "leg-29", topic: "itp-legal", q: "Which best explains why the IT Act, 2000's cybercrime-specific sections are only briefly mentioned in this topic?", options: ["Because the IT Act has no cybercrime provisions at all", "Those provisions (offences, penalties, the National Cyber Security Policy 2013) are covered in depth in the dedicated Cyber Security unit; this topic instead focuses on the IT Act's civil/commercial role", "Because cybercrime is governed exclusively by the DPDP Act", "Because cybercrime provisions were repealed and no longer exist"], answer: 1, exp: "Cybercrime-specific IT Act provisions are covered in depth elsewhere (the Cyber Security unit), so this topic emphasizes the Act's civil/commercial role." },
  { id: "leg-30", topic: "itp-legal", q: "Which of these best illustrates the IT Act, 2000's legal-recognition function in practice?", options: ["A court refusing to accept any electronic evidence under any circumstance", "A government department requiring every digital document to also be separately notarized on paper before it has any legal effect", "A court accepting a digitally signed electronic contract as valid evidence, on the same legal footing as a signed paper contract", "A private company being exempted entirely from any contract law"], answer: 2, exp: "This is the core practical effect of the IT Act's legal-recognition provisions — electronic records/signatures standing on equal legal footing with paper." },
  { id: "leg-31", topic: "itp-legal", q: "Which of these best illustrates the DPDP Act, 2023's consent-based processing requirement in practice?", options: ["A company collecting and freely reselling any user's personal data with no notice or agreement", "A government department publishing a citizen's private medical records without their knowledge", "An app that collects no personal data at all, making consent irrelevant to it", "A mobile app asking a user to explicitly agree before it collects and processes their personal data for a stated purpose"], answer: 3, exp: "Explicit consent before processing personal data for a stated purpose is exactly what the DPDP Act's consent framework requires." },
  { id: "leg-32", topic: "itp-legal", q: "Which of these best illustrates the Aadhaar Act, 2016's 'targeted delivery' provision in practice?", options: ["A subsidized cooking-gas scheme requiring Aadhaar-based authentication to confirm the beneficiary's identity before crediting the subsidy", "A private company using Aadhaar data for unrelated marketing purposes with no legal basis", "A copyright dispute over a software product's source code", "A citizen filing an RTI request for information about a scheme's budget"], answer: 0, exp: "Aadhaar-based authentication as a condition for a targeted subsidy is exactly what Section 7's targeted-delivery provision enables." },
  { id: "leg-33", topic: "itp-legal", q: "Which of these best illustrates the Copyright Act, 1957's protection of software in practice?", options: ["A citizen requesting information about a government scheme's budget", "A software company obtaining legal recourse against a competitor who copied significant portions of its proprietary source code without permission", "A bank verifying a customer's identity through Aadhaar authentication", "A data fiduciary obtaining consent before processing personal data"], answer: 1, exp: "Legal recourse against unauthorized copying of source code is a direct, practical illustration of the Copyright Act's protection of software." },
  { id: "leg-34", topic: "itp-legal", q: "Which of these best illustrates the RTI Act, 2005 in practice?", options: ["A company registering a digital signature certificate with a Certifying Authority", "A citizen consenting to a mobile app's data-processing terms", "A citizen formally requesting, from a government department, details of how funds under a specific welfare scheme were spent", "A software company registering copyright for its source code"], answer: 2, exp: "A formal request to a government department for information on scheme spending is a textbook example of the RTI Act in action." },
  { id: "leg-35", topic: "itp-legal", q: "Which best summarizes how the IT Act 2000, DPDP Act 2023, Aadhaar Act 2016, Copyright Act 1957 and RTI Act 2005 together form India's IT legislative framework?", options: ["They are five interchangeable versions of the same law with no distinct scope", "Only one of these Acts has any practical relevance; the rest are purely symbolic", "They apply only to private companies, with no relevance to government IT projects", "Each addresses a distinct but complementary dimension — legal validity of electronic transactions, personal data protection, Aadhaar-specific identity/benefit delivery, software IP protection, and citizen access to information/accountability — collectively enabling and governing India's digital ecosystem"], answer: 3, exp: "Each of these five Acts covers a distinct, complementary dimension of India's overall IT legislative framework." },
  { id: "leg-36", topic: "itp-legal", q: "A government department wants to publish a dataset of aggregated (non-personal) scheme statistics online for public use. Which Act most directly supports this kind of transparency initiative?", options: ["The RTI Act, 2005, whose transparency principle underpins the broader push toward proactive disclosure of government-held information", "The Aadhaar Act, 2016, which governs identity authentication, not data publication", "The Copyright Act, 1957, which protects creative works, not government transparency", "No Act has any bearing on this scenario"], answer: 0, exp: "The RTI Act's transparency principle underpins proactive government disclosure initiatives of this kind." },
  { id: "leg-37", topic: "itp-legal", q: "If a Data Fiduciary under the DPDP Act, 2023 fails to meet its obligations regarding a Data Principal's personal data, the matter can be taken up before:", options: ["The Controller of Certifying Authorities exclusively", "The Data Protection Board of India", "NIXI", "GESIA"], answer: 1, exp: "The Data Protection Board of India is the dedicated enforcement body for Data Fiduciary obligation failures under the DPDP Act." },
  { id: "leg-38", topic: "itp-legal", q: "Which best describes the legal chain that gives a citizen's DigiLocker-issued certificate the same standing as a paper original?", options: ["The Aadhaar Act, 2016, which has no bearing on document validity", "The Copyright Act, 1957, which protects authorship, not document validity", "The IT Act, 2000's recognition of electronic records and digital/electronic signatures gives the digitally issued, signed document legal validity", "No law gives such documents legal standing"], answer: 2, exp: "The IT Act's recognition of electronic records/signatures is the legal basis for DigiLocker documents' validity." },
  { id: "leg-39", topic: "itp-legal", q: "Which of the following is NOT one of the five Acts covered in this topic's legislative framework for IT in India?", options: ["The IT Act, 2000", "The Aadhaar Act, 2016", "The DPDP Act, 2023", "The Indian Contract Act, 1872, which is not specific to IT/electronic transactions and is not covered here"], answer: 3, exp: "The Indian Contract Act, 1872 is a general contract law, not one of the five IT-specific Acts covered in this topic." },
  { id: "leg-40", topic: "itp-legal", q: "Why is it important to distinguish the DPDP Act, 2023 from the RTI Act, 2005 in exam preparation?", options: ["Because they serve opposing-sounding but complementary goals — data protection (limiting disclosure of personal data) versus right to information (enabling disclosure of public-authority information) — and are easy to confuse if not studied carefully", "Because they are legally identical and interchangeable", "Because only one of the two Acts actually exists", "Because neither Act has any relevance to e-governance"], answer: 0, exp: "These two Acts pursue opposite-sounding goals (limiting versus enabling disclosure), which is exactly why careful distinction matters." },
  { id: "leg-41", topic: "itp-legal", q: "A Certifying Authority operating under the IT Act, 2000's regulatory structure is licensed and overseen by:", options: ["The Data Protection Board of India", "The Controller of Certifying Authorities (CCA)", "UIDAI", "The Central Information Commission"], answer: 1, exp: "The Controller of Certifying Authorities licenses and oversees Certifying Authorities under the IT Act." },
  { id: "leg-42", topic: "itp-legal", q: "Which best explains why the DPDP Act, 2023 was needed even though the IT Act, 2000 already existed?", options: ["The IT Act had already fully addressed personal data protection with no gaps", "The DPDP Act was needed to repeal the Aadhaar Act entirely", "The IT Act's data-related provisions were comparatively narrow, and India needed a comprehensive, dedicated statute specifically addressing consent-based personal data processing and providing a specialized enforcement body", "No additional data-protection legislation was actually needed"], answer: 2, exp: "The IT Act's data provisions were comparatively narrow, motivating a dedicated, comprehensive statute like the DPDP Act." },
  { id: "leg-43", topic: "itp-legal", q: "Which Act specifically established the legal basis for a citizen's Aadhaar number to be used for authenticating eligibility for a subsidized government scheme?", options: ["The Copyright Act, 1957", "The RTI Act, 2005", "The IT Act, 2000, which does not itself establish Aadhaar's legal basis", "The Aadhaar Act, 2016"], answer: 3, exp: "The Aadhaar Act, 2016 specifically provides the legal basis for Aadhaar-based authentication in targeted benefit delivery." },
  { id: "leg-44", topic: "itp-legal", q: "Which Act would a company primarily rely on to legally protect its mobile application's underlying source code from being copied by a competitor?", options: ["The Copyright Act, 1957", "The Aadhaar Act, 2016", "The RTI Act, 2005", "The DPDP Act, 2023"], answer: 0, exp: "The Copyright Act, 1957 is the primary source of legal protection for a company's software source code." },
  { id: "leg-45", topic: "itp-legal", q: "Which Act would a citizen rely on to request a copy of the feasibility study behind a proposed government e-governance project?", options: ["The Copyright Act, 1957", "The RTI Act, 2005", "The Aadhaar Act, 2016", "The IT Act, 2000, which does not itself grant a right to request government information"], answer: 1, exp: "The RTI Act, 2005 grants citizens the right to request such information from a public authority." },
  { id: "leg-46", topic: "itp-legal", q: "Which Act would primarily govern whether an e-commerce company can lawfully use a customer's browsing history to personalize offers, absent any specific consent obtained for that purpose?", options: ["The Copyright Act, 1957", "The RTI Act, 2005", "The DPDP Act, 2023", "The Aadhaar Act, 2016, which is specific to Aadhaar-based authentication, not general data use"], answer: 2, exp: "The DPDP Act, 2023 governs the lawful basis for processing personal data such as browsing history, including where consent is required." },
  { id: "leg-47", topic: "itp-legal", q: "Which Act gives a digitally signed loan agreement, executed entirely online, the same legal standing as a signed paper agreement?", options: ["The RTI Act, 2005", "The Copyright Act, 1957", "The Aadhaar Act, 2016, which governs identity authentication rather than the general validity of electronic contracts", "The IT Act, 2000"], answer: 3, exp: "The IT Act, 2000's recognition of electronic records/signatures gives a digitally signed online agreement equal legal standing to a paper one." },
  { id: "leg-48", topic: "itp-legal", q: "Overall, which best describes the purpose of studying India's legislative framework for IT together, rather than each Act in isolation?", options: ["Because a single real-world digital service (like an eKYC-based fintech app or a DigiLocker-issued certificate) often depends on several of these Acts working together — e.g. the IT Act for legal validity, the Aadhaar Act for authentication, and the DPDP Act for data-handling obligations", "Because these Acts have no practical relationship to each other", "Because only one Act is ever relevant to any real digital service", "Because studying them together is explicitly discouraged by law"], answer: 0, exp: "Real digital services typically depend on several of these Acts working together, which is why they are best studied as a connected framework." },
  { id: "leg-49", topic: "itp-legal", q: "Which best captures the difference in emphasis between the IT Act, 2000 and the DPDP Act, 2023?", options: ["They are functionally identical laws passed in the same year", "The IT Act broadly enables lawful electronic transactions and recognizes electronic records/signatures; the DPDP Act specifically protects individuals' personal data during processing, with its own consent framework and enforcement board", "The IT Act is about personal data protection while the DPDP Act is about digital signatures — the reverse of their actual focus", "Neither Act has any relevance to real digital services"], answer: 1, exp: "The IT Act enables lawful electronic transactions broadly, while the DPDP Act specifically protects personal data during processing." },
  { id: "leg-50", topic: "itp-legal", q: "Overall, the IT Act 2000's civil/commercial provisions, the DPDP Act 2023, the Aadhaar Act 2016, the Copyright Act 1957's software protection, and the RTI Act 2005 together illustrate:", options: ["An arbitrary, unrelated collection of laws with no shared relevance to IT projects", "A framework applicable only to private companies, with no bearing on government e-governance projects", "A legislative framework where the legal validity of digital transactions, protection of personal data, a specific identity/benefit-delivery system, protection of software as intellectual property, and citizen access to information collectively enable — and hold accountable — India's expanding digital government and IT ecosystem", "A single Act repeated under five different names"], answer: 2, exp: "Together, these five Acts both enable and hold accountable India's expanding digital government and IT ecosystem." }

);
